static void ImportRGBOQuantum(const Image *image,QuantumInfo *quantum_info, /* <=== ImportRGBOQuantum */ 
  const MagickSizeType number_pixels,const unsigned char *magick_restrict p,
  Quantum *magick_restrict q)
{
  QuantumAny
    range;

  register ssize_t
    x;

